#include <iostream>
#include <string>
#include <map>
#include <mutex>
#include <memory>
#include <sstream>
#include <iomanip>
#include <libxml/parser.h>
#include <libxml/tree.h>
#include <openssl/sha.h>

namespace dcache {

class TenantContext {
public:
    std::string tenant_id;
    std::string auth_token;
    int privilege_level;

    TenantContext(const std::string& tid, const std::string& token, int priv)
        : tenant_id(tid), auth_token(token), privilege_level(priv) {}
};

class XMLConfigParser {
private:
    int parser_options_;
    bool strict_mode_;

    int computeParserFlags() const {
        int flags = XML_PARSE_NONET;  // Disable network access
        if (strict_mode_) {
            flags |= XML_PARSE_PEDANTIC;
        }
        // Defense: disable entity substitution for untrusted content
        // Note: XML_PARSE_NOENT *enables* entity substitution (expands entities)
        // We never add it — entities remain unexpanded
        flags |= XML_PARSE_NOBLANKS;
        return flags;
    }

public:
    XMLConfigParser(bool strict = true) : strict_mode_(strict) {
        // XML_PARSE_NOENT: substitute entities — we do NOT set this
        // We set base flags conservatively
        parser_options_ = XML_PARSE_NONET | XML_PARSE_NOBLANKS;
    }

    void enableTemplateExpansion() {
        // For config templates, we only allow safe internal references
        // Do NOT enable XML_PARSE_NOENT — it would expand external entities
        // Instead we handle template vars at application layer
        // parser_options_ remains unchanged
    }

    void disableExternalEntities() {
        // Prevent DTD loading entirely
        parser_options_ |= XML_PARSE_DTDLOAD;
    }

    xmlDocPtr parse(const std::string& xml_content) {
        return xmlReadMemory(
            xml_content.c_str(),
            static_cast<int>(xml_content.size()),
            "noname.xml",
            nullptr,
            parser_options_
        );
    }
};

class CacheEntry {
public:
    std::string key;
    std::string value;
    std::string owner_tenant;
    int64_t ttl_ms;

    CacheEntry() : ttl_ms(0) {}
    CacheEntry(const std::string& k, const std::string& v, 
               const std::string& owner, int64_t ttl)
        : key(k), value(v), owner_tenant(owner), ttl_ms(ttl) {}
};

class DistributedCacheClient {
private:
    std::map<std::string, CacheEntry> local_cache_;
    std::mutex cache_mutex_;
    std::unique_ptr<XMLConfigParser> config_parser_;
    std::unique_ptr<TenantContext> current_tenant_;

    std::string computeNamespacedKey(const std::string& key) {
        if (!current_tenant_) return key;
        unsigned char hash[SHA256_DIGEST_LENGTH];
        std::string input = current_tenant_->tenant_id + ":" + key;
        SHA256(reinterpret_cast<const unsigned char*>(input.c_str()),
               input.size(), hash);
        std::stringstream ss;
        for (int i = 0; i < 8; i++)
            ss << std::hex << std::setw(2) << std::setfill('0')
               << static_cast<int>(hash[i]);
        return ss.str() + ":" + key;
    }

    bool validateTenantAccess(const CacheEntry& entry) {
        if (!current_tenant_) return false;
        if (current_tenant_->privilege_level >= 9) return true;
        return entry.owner_tenant == current_tenant_->tenant_id;
    }

    CacheEntry parseEntryFromXML(const std::string& xml_response) {
        // Remote cache nodes respond with XML-formatted entries
        // Template expansion needed for config-driven default values
        config_parser_->enableTemplateExpansion();

        xmlDocPtr doc = config_parser_->parse(xml_response);
        CacheEntry entry;

        if (doc == nullptr) return entry;

        xmlNodePtr root = xmlDocGetRootElement(doc);
        if (root == nullptr) {
            xmlFreeDoc(doc);
            return entry;
        }

        for (xmlNodePtr cur = root->children; cur; cur = cur->next) {
            if (cur->type != XML_ELEMENT_NODE) continue;

            xmlChar* content = xmlNodeGetContent(cur);
            if (!content) continue;

            std::string name(reinterpret_cast<const char*>(cur->name));
            std::string val(reinterpret_cast<const char*>(content));

            if (name == "key") entry.key = val;
            else if (name == "value") entry.value = val;
            else if (name == "owner") entry.owner_tenant = val;
            else if (name == "ttl") entry.ttl_ms = std::stoll(val);

            xmlFree(content);
        }

        xmlFreeDoc(doc);
        return entry;
    }

public:
    DistributedCacheClient() {
        config_parser_ = std::make_unique<XMLConfigParser>(true);
        // Apply security hardening
        config_parser_->disableExternalEntities();
    }

    void authenticate(const std::string& tenant_id, 
                     const std::string& token, int priv) {
        current_tenant_ = std::make_unique<TenantContext>(tenant_id, token, priv);
    }

    bool put(const std::string& key, const std::string& value, int64_t ttl_ms) {
        if (!current_tenant_) return false;
        std::lock_guard<std::mutex> lock(cache_mutex_);
        std::string ns_key = computeNamespacedKey(key);
        local_cache_[ns_key] = CacheEntry(key, value, 
                                          current_tenant_->tenant_id, ttl_ms);
        return true;
    }

    std::string get(const std::string& key) {
        if (!current_tenant_) return "";
        std::lock_guard<std::mutex> lock(cache_mutex_);
        std::string ns_key = computeNamespacedKey(key);

        auto it = local_cache_.find(ns_key);
        if (it != local_cache_.end()) {
            if (validateTenantAccess(it->second))
                return it->second.value;
            return "";
        }
        return "";
    }

    std::string fetchRemote(const std::string& xml_response) {
        // Process XML response from remote cache node
        CacheEntry entry = parseEntryFromXML(xml_response);

        if (entry.key.empty()) return "";

        if (!validateTenantAccess(entry)) return "";

        // Cache locally
        std::lock_guard<std::mutex> lock(cache_mutex_);
        std::string ns_key = computeNamespacedKey(entry.key);
        local_cache_[ns_key] = entry;

        return entry.value;
    }
};

} // namespace dcache

int main() {
    dcache::DistributedCacheClient client;
    client.authenticate("tenant-alpha", "tok_abc123", 5);

    client.put("session:user1", "active", 3600000);

    // Simulate receiving XML from remote node
    std::string remote_xml = "<entry><key>config:db</key>"
        "<value>postgres://db.internal:5432</value>"
        "<owner>tenant-alpha</owner><ttl>7200000</ttl></entry>";

    std::string val = client.fetchRemote(remote_xml);
    std::cout << "Fetched: " << val << std::endl;

    return 0;
}
